//! Shared benchmark configuration.

use serde::{Deserialize, Serialize};

pub(crate) const MAX_CONCURRENCY: usize = 64;
/// Serialized configuration bound shared by setup and every configuration reader.
pub(crate) const MAX_CONFIG_BYTES: usize = 64 * 1024;
/// Project-relative home for logs generated by ASB defaults.
///
/// Explicit `log_file` selections retain their location.  Keeping defaults in
/// one hidden directory lets a project root remain useful for source,
/// configuration, and report files.
pub(crate) const DEFAULT_LOG_DIRECTORY: &str = ".asb-logs";

/// Small, extensible benchmark configuration written by `asb setup`.
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct BenchmarkConfig {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(crate) planning: Option<crate::planning::PlanningConfig>,
    pub agent: String,
    pub workload: String,
    pub provider: String,
    pub model: String,
    /// Number of identical agent executions to run concurrently.
    #[serde(
        default = "default_concurrency",
        deserialize_with = "deserialize_concurrency"
    )]
    pub concurrency: usize,
    /// Optional trial-set TOML selected for an external workload.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub trial_set: Option<String>,
    /// Optional trial identifier within the selected trial set.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub trial: Option<String>,
    #[serde(default = "default_workspace")]
    pub workspace: String,
    #[serde(default = "default_log_file")]
    pub log_file: String,
    #[serde(default)]
    pub measurements: Option<MeasurementConfig>,
    /// Explicit storage policy for completed, independently graded attempts.
    ///
    /// The default retains the existing recovery-oriented behavior.  Compact
    /// mode never deletes an incomplete or uncertain attempt: it requires the
    /// workload adapter to report that its owned execution resources were
    /// removed after durable grading artifacts were written.
    #[serde(default)]
    pub retention: RetentionConfig,
    /// Explicit stdio MCP servers made available to an adapter that supports
    /// ordinary MCP configuration.  The command remains an argument array;
    /// ASB never routes it through a shell.
    #[serde(
        default,
        skip_serializing_if = "Vec::is_empty",
        deserialize_with = "deserialize_mcp_servers"
    )]
    pub(crate) mcp_servers: Vec<McpServerConfig>,
}

/// Storage policy for one benchmark execution.
#[derive(Clone, Debug, Default, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct RetentionConfig {
    /// Release completed task containers/workspaces after their official grade
    /// and bounded evidence have been retained.  Failed or uncertain attempts
    /// remain preserved for recovery and inspection.
    #[serde(default)]
    pub compact_completed_attempts: bool,
}

/// A named, bounded stdio MCP server declaration.
///
/// The name is a stable configuration identifier, not a display label.  A
/// later adapter-integration step decides whether it can materialize this
/// declaration for a particular client.  Keeping this record declarative
/// means parsing it cannot start a subprocess or contact a provider.
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct McpServerConfig {
    pub(crate) id: String,
    pub(crate) program: String,
    #[serde(default)]
    pub(crate) args: Vec<String>,
}

/// Measurement modules selected by generated setup files.
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub struct MeasurementConfig {
    pub enabled: bool,
    pub directory: String,
    pub collectors: Vec<String>,
}

fn default_workspace() -> String {
    "./asb-workspace".into()
}

pub(crate) fn default_log_path(name: &str) -> String {
    format!("{DEFAULT_LOG_DIRECTORY}/{name}")
}

fn default_log_file() -> String {
    default_log_path("benchmark.log")
}

fn default_concurrency() -> usize {
    1
}

fn deserialize_concurrency<'de, D>(deserializer: D) -> Result<usize, D::Error>
where
    D: serde::Deserializer<'de>,
{
    let value = usize::deserialize(deserializer)?;
    if value == 0 {
        return Err(serde::de::Error::custom("concurrency must be at least 1"));
    }
    if value > MAX_CONCURRENCY {
        return Err(serde::de::Error::custom(format!(
            "concurrency must not exceed {MAX_CONCURRENCY}; split larger selections into bounded sweeps"
        )));
    }
    Ok(value)
}

/// Bound aggregate relay storage and process overhead per benchmark.  Four
/// independent stdio services cover the ordinary filesystem, repository,
/// issue-tracker and domain-tool split without turning a measurement run into
/// an MCP service farm.
const MAX_MCP_SERVERS: usize = 4;
const MAX_MCP_ARGUMENTS: usize = 64;
const MAX_MCP_IDENTIFIER_BYTES: usize = 64;
const RESERVED_MCP_SERVER_ID: &str = "asb_tool_replay";

fn deserialize_mcp_servers<'de, D>(deserializer: D) -> Result<Vec<McpServerConfig>, D::Error>
where
    D: serde::Deserializer<'de>,
{
    let servers = Vec::<McpServerConfig>::deserialize(deserializer)?;
    validate_mcp_servers(&servers).map_err(serde::de::Error::custom)?;
    Ok(servers)
}

fn validate_mcp_servers(servers: &[McpServerConfig]) -> Result<(), String> {
    if servers.len() > MAX_MCP_SERVERS {
        return Err(format!(
            "mcp_servers must not contain more than {MAX_MCP_SERVERS} servers"
        ));
    }
    let mut names = std::collections::BTreeSet::new();
    for server in servers {
        if server.id.is_empty()
            || server.id.len() > MAX_MCP_IDENTIFIER_BYTES
            || !server.id.bytes().enumerate().all(|(index, byte)| {
                matches!(byte, b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_')
                    && (index > 0 || byte.is_ascii_lowercase() || byte.is_ascii_digit())
            })
        {
            return Err(format!(
                "MCP server id `{}` must use 1 to {MAX_MCP_IDENTIFIER_BYTES} lowercase ASCII letters, digits, hyphens, or underscores and cannot start with a hyphen or underscore",
                server.id
            ));
        }
        crate::selection_names::validate(&server.id, "MCP server")?;
        if server.id == RESERVED_MCP_SERVER_ID {
            return Err(format!(
                "MCP server id `{RESERVED_MCP_SERVER_ID}` is reserved for ASB local-tool replay"
            ));
        }
        if !names.insert(&server.id) {
            return Err(format!("MCP server id `{}` is duplicated", server.id));
        }
        if server.program.trim().is_empty() {
            return Err(format!(
                "MCP server `{}` program must not be empty",
                server.id
            ));
        }
        if server.args.len() > MAX_MCP_ARGUMENTS {
            return Err(format!(
                "MCP server `{}` must not have more than {MAX_MCP_ARGUMENTS} arguments",
                server.id
            ));
        }
        if server.args.iter().any(|argument| argument.is_empty()) {
            return Err(format!(
                "MCP server `{}` arguments must not contain empty values",
                server.id
            ));
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::{BenchmarkConfig, MAX_MCP_ARGUMENTS, MAX_MCP_SERVERS, default_log_path};

    #[test]
    fn concurrency_defaults_to_one_and_accepts_positive_values() {
        let config: BenchmarkConfig = toml::from_str(
            "agent='pi'\nworkload='bug-fix'\nprovider='openrouter'\nmodel='tool-model'\n",
        )
        .expect("default configuration parses");
        assert_eq!(config.concurrency, 1);
        assert_eq!(config.log_file, ".asb-logs/benchmark.log");

        let config: BenchmarkConfig = toml::from_str(
            "agent='pi'\nworkload='bug-fix'\nprovider='openrouter'\nmodel='tool-model'\nconcurrency=3\n",
        )
        .expect("positive concurrency parses");
        assert_eq!(config.concurrency, 3);
    }

    #[test]
    fn compact_retention_is_opt_in_and_rejects_unknown_fields() {
        let default: BenchmarkConfig = toml::from_str(
            "agent='fixture'\nworkload='bug-fix'\nprovider='fixture'\nmodel='fixture'\n",
        )
        .unwrap();
        assert!(!default.retention.compact_completed_attempts);
        let compact: BenchmarkConfig = toml::from_str(
            "agent='fixture'\nworkload='bug-fix'\nprovider='fixture'\nmodel='fixture'\n[retention]\ncompact_completed_attempts=true\n",
        )
        .unwrap();
        assert!(compact.retention.compact_completed_attempts);
        assert!(toml::from_str::<BenchmarkConfig>(
            "agent='fixture'\nworkload='bug-fix'\nprovider='fixture'\nmodel='fixture'\n[retention]\nunknown=true\n"
        )
        .is_err());
    }

    #[test]
    fn zero_concurrency_is_rejected() {
        let error = toml::from_str::<BenchmarkConfig>(
            "agent='pi'\nworkload='bug-fix'\nprovider='openrouter'\nmodel='tool-model'\nconcurrency=0\n",
        )
        .expect_err("zero concurrency must be invalid");
        assert!(error.to_string().contains("concurrency must be at least 1"));
    }

    #[test]
    fn concurrency_is_bounded_before_replica_allocation() {
        for concurrency in [64u64, 65, u64::MAX] {
            let config = format!(
                "agent='pi'\nworkload='bug-fix'\nprovider='cli2key'\nmodel='fixture'\nconcurrency={concurrency}\n"
            );
            let parsed = toml::from_str::<BenchmarkConfig>(&config);
            if concurrency == 64 {
                assert_eq!(parsed.unwrap().concurrency, 64);
            } else {
                assert!(parsed.is_err());
            }
        }
    }

    #[test]
    fn default_logs_are_collected_under_the_hidden_log_directory() {
        assert_eq!(default_log_path("run.jsonl"), ".asb-logs/run.jsonl");
    }

    #[test]
    fn mcp_servers_parse_as_bounded_typed_declarations() {
        let config: BenchmarkConfig = toml::from_str(
            "agent='pi'\nworkload='bug-fix'\nprovider='openrouter'\nmodel='tool-model'\n[[mcp_servers]]\nid='filesystem'\nprogram='npx'\nargs=['-y','@modelcontextprotocol/server-filesystem','.']\n",
        )
        .expect("valid MCP declaration parses");
        assert_eq!(config.mcp_servers.len(), 1);
        assert_eq!(config.mcp_servers[0].id, "filesystem");
        assert_eq!(config.mcp_servers[0].program, "npx");
        assert_eq!(config.mcp_servers[0].args.len(), 3);
        let encoded = toml::to_string(&config).expect("configuration serializes");
        assert!(encoded.contains("[[mcp_servers]]"));
    }

    #[test]
    fn mcp_servers_reject_unknown_duplicate_and_unbounded_declarations() {
        for invalid in [
            "[[mcp_servers]]\nid='filesystem'\nprogram='server'\nunexpected=true\n",
            "[[mcp_servers]]\nid='filesystem'\nprogram='server'\n[[mcp_servers]]\nid='filesystem'\nprogram='other'\n",
            "[[mcp_servers]]\nid='ALL'\nprogram='server'\n",
            "[[mcp_servers]]\nid='asb_tool_replay'\nprogram='server'\n",
            "[[mcp_servers]]\nid='filesystem'\nprogram=' '\n",
        ] {
            let text = format!(
                "agent='pi'\nworkload='bug-fix'\nprovider='openrouter'\nmodel='tool-model'\n{invalid}"
            );
            assert!(
                toml::from_str::<BenchmarkConfig>(&text).is_err(),
                "{invalid}"
            );
        }

        let too_many_servers = (0..=MAX_MCP_SERVERS)
            .map(|index| format!("[[mcp_servers]]\nid='server-{index}'\nprogram='server'\n"))
            .collect::<String>();
        let too_many_arguments = format!(
            "[[mcp_servers]]\nid='filesystem'\nprogram='server'\nargs=[{}]\n",
            (0..=MAX_MCP_ARGUMENTS)
                .map(|_| "'argument'")
                .collect::<Vec<_>>()
                .join(",")
        );
        for invalid in [too_many_servers, too_many_arguments] {
            let text = format!(
                "agent='pi'\nworkload='bug-fix'\nprovider='openrouter'\nmodel='tool-model'\n{invalid}"
            );
            assert!(
                toml::from_str::<BenchmarkConfig>(&text).is_err(),
                "{invalid}"
            );
        }
    }

    #[test]
    fn benchmark_configuration_rejects_unknown_top_level_fields() {
        let error = toml::from_str::<BenchmarkConfig>(
            "agent='pi'\nworkload='bug-fix'\nprovider='openrouter'\nmodel='tool-model'\nunknown=true\n",
        )
        .expect_err("unknown top-level field must be rejected");
        assert!(error.to_string().contains("unknown field"));
    }
}
